import java.io.*;
import java.util.*;

public class CF1278F extends PrintWriter {
    CF1278F() { super(System.out, true); }
    Scanner sc = new Scanner(System.in);
    public static void main(String[] args) {
        CF1278F obj = new CF1278F(); obj.solve(); obj.flush();
    }

    static final int MOD = 998244353;
    int gcdRes, xCoef, yCoef;

    void computeGCD(int a, int b) {
        if (b == 0) {
            gcdRes = a; xCoef = 1; yCoef = 0;
        } else {
            computeGCD(b, a % b);
            int tempX = xCoef - a / b * yCoef;
            xCoef = yCoef;
            yCoef = tempX;
        }
    }

    int modularInverse(int a) {
        computeGCD(a, MOD);
        return xCoef < 0 ? xCoef + MOD : xCoef;
    }

    void solve() {
        int nVal = sc.nextInt();
        int mVal = sc.nextInt();
        int invM = modularInverse(mVal);
        int kVal = sc.nextInt();

        int[] dp = new int[kVal + 1];
        dp[0] = 1;

        for (int i = 0; i < kVal; i++) {
            for (int d = kVal - 1; d >= 0; d--) {
                if (dp[d] != 0) {
                    dp[d + 1] = (int) ((dp[d + 1] + (long) dp[d] * (nVal - d)) % MOD);
                    dp[d] = (int) ((long) dp[d] * d % MOD);
                }
            }
        }

        long p = 1, answer = 0;
        for (int d = 1; d <= kVal; d++) {
            p = p * invM % MOD;
            answer = (answer + dp[d] * p) % MOD;
        }
        println(answer);
    }
}
